# Illustrative pattern: the prefix never changes, so repeats can bill as cache hits.
STABLE_PREFIX = [
    {"role": "system", "content": SYSTEM_PROMPT},  # never edited mid-session
    {"role": "user", "content": REPO_CONTEXT},     # fixed files, fixed order
]

def build_messages(history, new_turn):
    # Anything that edits STABLE_PREFIX (a timestamp, a reordered tool list)
    # turns the next request back into fresh input.
    return STABLE_PREFIX + history + [new_turn]

def step(send, history, new_turn, output_cap):
    # `send` is your own client wrapper; cap the visible output on every step.
    return send(messages=build_messages(history, new_turn), max_output=output_cap)
